include!("solution.rs");
#[test]
fn hidden_cases() {
    assert_eq!(solve("".to_string()), "".to_string(), "case 0");
    assert_eq!(solve("A".to_string()), "1A".to_string(), "case 1");
    assert_eq!(solve("AA".to_string()), "2A".to_string(), "case 2");
    assert_eq!(solve("AB".to_string()), "1A1B".to_string(), "case 3");
    assert_eq!(solve("AAABB".to_string()), "3A2B".to_string(), "case 4");
    assert_eq!(solve("ABBA".to_string()), "1A2B1A".to_string(), "case 5");
    assert_eq!(
        solve("ZZZZZZZZZZZZ".to_string()),
        "12Z".to_string(),
        "case 6"
    );
    assert_eq!(
        solve("ABCABC".to_string()),
        "1A1B1C1A1B1C".to_string(),
        "case 7"
    );
    assert_eq!(
        solve("AAAABCCCC".to_string()),
        "4A1B4C".to_string(),
        "case 8"
    );
    assert_eq!(solve("AZZA".to_string()), "1A2Z1A".to_string(), "case 9");
    assert_eq!(solve("".to_string()), "1000A".to_string(), "case 10");
    assert_eq!(solve("XXYYYZ".to_string()), "2X3Y1Z".to_string(), "case 11");
}
